INSERT INTO `services` (`id`, `municipality_id`, `department_id`, `category_id`, `name`, `description`, `instructions`, `estimated_days`, `status`, `created_at`, `updated_at`) VALUES
(252, 1, 770, 198, 'Request Environmental Health Assistance', 'Submit an enquiry about a sanitation, hygiene or environmental health concern.', 'Describe the concern and provide the location. The responsible authority will assess the matter.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(253, 1, 770, 198, 'Report Illegal Dumping', 'Notify the council about suspected illegal dumping on land within its area of responsibility.', 'Provide the location, a description of the dumping and supporting photographs if available.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(254, 1, 965, 201, 'Enquire About Local Trading Permits', 'Ask whether a local authority permit or approval applies to your proposed activity.', 'Describe the business activity and location. The council will advise whether it handles the relevant approval.', 7, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(255, 1, 965, 201, 'Enquire About Market Stall Applications', 'Request information about applying for a market stall or trading space managed by the local authority.', 'Describe the proposed business activity and preferred location. Availability, documents and fees must be confirmed by the council.', 7, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(256, 1, 961, 202, 'Submit Service Feedback', 'Provide feedback about your experience with a local authority service.', 'Describe your experience and the service concerned. Do not include passwords or unnecessary sensitive information.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(257, 1, 961, 202, 'Request Assistance With an Application', 'Ask for help understanding the requirements or progress of an existing council application.', 'Provide the application reference if available and explain what assistance you need.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(258, 1, 961, 202, 'Submit a General Council Enquiry', 'Ask a question about local authority services, procedures or responsibilities.', 'Explain your question clearly and provide contact details for a response.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(259, 1, 962, 196, 'Request an Account Statement', 'Request information about obtaining a statement for an existing local authority account.', 'Provide your account reference and the contact details needed to verify your enquiry.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(260, 1, 962, 196, 'Enquire about a Local Authority Account', 'Submit an enquiry about opening or updating an account with your local authority.', 'Provide the relevant account details and contact information. The council will advise you about applicable requirements.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(261, 1, 963, 197, 'Enquire About Property Valuation', 'Request information about property valuation or related local authority procedures.', 'Provide the property location and explain the information you need.', 7, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(262, 1, 963, 197, 'Enquire About Building-Plan Approval', 'Request guidance about building-plan submission and approval procedures.', 'Describe your proposed building project and property location. The council will confirm the required documents and applicable fees.', 7, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(263, 1, 963, 197, 'Follow Up on a Land Application', 'Request an update on an existing land or plot application.', 'Provide your application reference number and any other details requested by the council.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(264, 1, 963, 197, 'Enquire About Residential Plots', 'Request information about residential land availability and the local authority application process.', 'Provide your contact details and the area of interest. Plot availability and application requirements must be confirmed by the council.', 10, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(265, 1, 964, 199, 'Report a Blocked Stormwater Drain', 'Report blocked stormwater drainage that may affect public roads or nearby properties.', 'Provide the exact location and explain the drainage problem. Include photographs if available.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(266, 1, 964, 199, 'Report a Damaged Public Road', 'Notify the council about damaged roads or potholes within its area of responsibility.', 'Describe the road damage and provide the street, area or nearest landmark.', 7, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(267, 1, 964, 199, 'Report a Faulty Streetlight', 'Report a streetlight that is not working where the council is responsible for its maintenance.', 'Provide the street or nearest landmark and the streetlight location.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(268, 1, 767, 198, 'Request Bulky-Waste Collection Information', 'Enquire about the collection or disposal of large household items where offered.', 'Describe the items and provide your collection location. Availability and any applicable charges must be confirmed by the council.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
