(1012, 35, 1133, 435, 'Enquire About Residential Plots', 'Request information about residential land availability and the local authority application process.', 'Provide your contact details and the area of interest. Plot availability and application requirements must be confirmed by the council.', 10, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
