(1016, 35, 937, 436, 'Request Bulky-Waste Collection Information', 'Enquire about the collection or disposal of large household items where offered.', 'Describe the items and provide your collection location. Availability and any applicable charges must be confirmed by the council.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(1017, 35, 937, 436, 'Enquire About Refuse Collection', 'Ask about refuse collection arrangements and collection schedules in your area.', 'Provide your street, area or property location so the council can advise you.', 3, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
