(1103, 40, 1154, 465, 'Report a Faulty Streetlight', 'Report a streetlight that is not working where the council is responsible for its maintenance.', 'Provide the street or nearest landmark and the streetlight location.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(1104, 40, 957, 464, 'Request Bulky-Waste Collection Information', 'Enquire about the collection or disposal of large household items where offered.', 'Describe the items and provide your collection location. Availability and any applicable charges must be confirmed by the council.', 5, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(1105, 40, 957, 464, 'Enquire About Refuse Collection', 'Ask about refuse collection arrangements and collection schedules in your area.', 'Provide your street, area or property location so the council can advise you.', 3, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(1106, 40, 958, 462, 'Enquire About a Water Disconnection', 'Ask about the requirements for disconnecting an existing water connection where applicable.', 'Provide the relevant account or property details. The council will confirm the applicable procedure.', 7, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10'),
(1107, 40, 958, 462, 'Enquire About a Water Connection', 'Ask about the process and requirements for a new water connection where this service is provided by the council.', 'Provide the property location and contact details. Connection availability, documents and fees must be confirmed by the council.', 7, 'inactive', '2026-10-14 21:10:10', '2026-10-14 21:10:10');
